# Navigation systems and en route charts: Instrument Flying Handbook FAA-H-8083-15B ch. 9 (VOR, DME,
# ILS, GPS), Instrument Procedures Handbook FAA-H-8083-16B ch. 2 (en route altitudes, COP, OROCA),
# AIM 1-1 and 1-2 (GPS, RAIM, CDI scaling), 14 CFR 91.177. ACS II.B, V.A, V.B.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "En route altitudes", "An airway segment shows an MEA of 6,000 and a MOCA of 4,800. When may you fly at 5,000 using a VOR?",
      ["Within 22 NM of the VOR", "Anywhere on the segment", "Only in radar contact"],
      "91.177 allows flight below the MEA down to the MOCA, but for VOR navigation only within 22 NM of the VOR, where signal reception is assured."),
    S(1, 2, "En route altitudes", "What does the minimum reception altitude (MRA) at an intersection ensure?",
      ["The fix can be identified", "Radar coverage at the fix", "Two-way radio contact with ATC"],
      "An MRA is the lowest altitude at which the intersection can be determined from the navaids that define it."),
    S(1, 2, "Changeover point", "On an airway with no changeover point shown, where should you switch to the next VOR?",
      ["Midway between the two VORs", "Over the first VOR", "At the next reporting point"],
      "The Instrument Procedures Handbook says to change frequencies midway between navaids unless a COP is charted with the distance to each one."),
    S(1, 3, "Localizer", "A localizer course is normally 5 degrees wide. Full-scale deflection means you are about:",
      ["2.5 degrees off course", "5 degrees off course", "10 degrees off course"],
      "Full-scale deflection on a 5-degree localizer comes at 2.5 degrees either side of centerline, four times the sensitivity of a VOR's 10 degrees."),
    S(1, 3, "Glide slope", "Why intercept the glide slope from below at the published altitude?",
      ["False glide slopes lie above it", "The signal is weaker from above it", "The localizer is unusable above it"],
      "Glide slope transmitters produce false courses at higher angles, the lowest near 9 to 12 degrees. Intercepting from the published altitude below avoids them."),
    S(1, 2, "GPS CDI scaling", "In terminal mode within 30 NM of the airport, what is GPS full-scale CDI deflection?",
      ["1 NM", "5 NM", "0.3 NM"],
      "AIM 1-1 describes en route sensitivity of plus or minus 5 NM, terminal of 1 NM within 30 NM of the airport, and approach of 0.3 NM at the final approach waypoint."),
    S(1, 2, "DME", "A DME identifier is heard only about once every 30 seconds, with no VOR identifier. What does it mean?",
      ["DME works but the VOR doesn't", "The VOR works but the DME doesn't", "Both are under maintenance"],
      "The DME identifier comes about once for every three or four VOR identifiers. Hearing only the DME tone means the DME is working but the VOR is not."),
    S(1, 3, "HSI interpretation", "Your HSI is set to 090 and shows a TO flag with the needle left. Which way is the course?",
      ["Left of the airplane", "Right of the airplane", "Behind the airplane"],
      "On an HSI the course needle shows where the selected course lies relative to the airplane symbol, so a needle left of center means the course is to the left."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "En route altitudes", "What does a minimum crossing altitude (MCA) require?",
      ["Crossing the fix at or above it", "Holding at the fix until cleared higher", "Descending to it right after the fix"],
      "91.177(b) requires crossing the fix at or above the MCA when proceeding toward a segment with a higher MEA and obstructions intervene."),
    S(2, 3, "En route altitudes", "What is a maximum authorized altitude (MAA)?",
      ["Highest usable altitude on a route", "Top of Class E airspace on the route", "Highest altitude allowed for VFR-on-top"],
      "An MAA is the highest altitude on an airway or route for which an MEA is designated at which adequate navigation signal reception is assured."),
    S(2, 2, "OROCA", "Over non-mountainous terrain, how much obstacle clearance does an OROCA give?",
      ["1,000 feet", "2,000 feet", "500 feet"],
      "An OROCA gives 1,000 feet of obstruction clearance in non-mountainous areas and 2,000 feet in designated mountainous areas, without assuring signal or radar coverage."),
    S(2, 3, "Glide slope", "The glide slope beam is normally about how thick?",
      ["1.4 degrees", "5 degrees", "3 degrees"],
      "The glidepath is normally 1.4 degrees thick, about 1,500 feet vertically 10 NM from touchdown and narrowing to a few feet at the runway."),
    S(2, 2, "Reverse sensing", "You track inbound on a VOR with the OBS set to the reciprocal of your course. What happens?",
      ["The needle senses in reverse", "The flag shows OFF and stays", "The DME stops reading distance"],
      "With the OBS set opposite to the course flown, the CDI reverses: corrections must be made away from the needle. Set the OBS to the course you intend to fly."),
    S(2, 3, "GPS CDI scaling", "When does the GPS CDI scale to 0.3 NM on an RNAV approach?",
      ["Nearing the final approach waypoint", "Passing the initial approach fix", "Inside 30 NM of the airport"],
      "Sensitivity ramps from 1 NM to 0.3 NM over the last 2 NM to the final approach waypoint, if approach mode is armed. Inside 30 NM it first changes from 5 NM to 1 NM."),
    S(2, 2, "RAIM", "Before a GPS-only approach without WAAS, what should you check?",
      ["Predicted RAIM availability", "The nearest VOR's Morse identifier", "The localizer's frequency"],
      "Without WAAS, integrity comes from RAIM. Check predicted RAIM availability for the ETA; flight service can give it for 1 hour either side of the ETA."),
    S(2, 3, "DME arc", "Flying a DME arc with the station off your left wingtip, the DME is increasing. What should you do?",
      ["Turn left toward the station", "Turn right, away from it", "Hold heading and wait for the DME"],
      "A rising DME on an arc means you are drifting outside it. Turning toward the station, here to the left, brings the airplane back to the arc distance."),
    # ---------- Drill only ----------
    S(0, 2, "En route altitudes", "What does a minimum turning altitude (MTA) at a fix provide?",
      ["Obstacle clearance during the turn", "Radar coverage through the turn", "A required holding altitude"],
      "The Instrument Procedures Handbook describes an MTA as a charted altitude giving vertical and lateral obstruction clearance based on turn criteria over certain fixes and route segments."),
    S(0, 2, "Minimum IFR altitude", "Off any published route in non-mountainous terrain, the minimum IFR altitude is how far above the highest obstacle within 4 NM?",
      ["1,000 feet", "2,000 feet", "1,500 feet"],
      "91.177(a)(2) sets 1,000 feet above the highest obstacle within 4 NM of the course, or 2,000 feet in designated mountainous areas."),
    S(0, 2, "VOT", "With a VOT tuned and the CDI centered, the OBS should read 0 degrees with which flag?",
      ["FROM", "TO", "OFF"],
      "A VOT radiates the 360 radial in all directions, so a centered needle should show 0 degrees FROM or 180 degrees TO."),
    S(0, 2, "WAAS", "What does WAAS add to GPS for approaches?",
      ["Vertical guidance and integrity", "Coverage only over the oceans", "Backup signals from VOR stations"],
      "WAAS corrects GPS signals and monitors their integrity, making precise vertical guidance possible, as on LPV approaches, without a RAIM check."),
    S(0, 3, "Navigation database", "Why check the GPS database is current before an RNAV approach?",
      ["Waypoints must match the chart", "An old database drains the battery", "It updates the terrain warning colors"],
      "An approach can be flown only if it is retrieved from a current database, so waypoints and procedures match the published chart."),
    S(0, 2, "ILS components", "Under 91.175, which may substitute for the ILS outer marker?",
      ["A DME fix in the procedure", "A VOR radial chosen by the pilot", "The middle marker"],
      "91.175(k) lists substitutes for the outer marker: compass locator, PAR or ASR, DME, VOR or NDB fixes authorized in the procedure, or a suitable RNAV fix."),
    S(0, 3, "Back course", "On a localizer back course with a conventional CDI, how do you correct?",
      ["Away from the needle", "Toward the needle", "By centering the OBS"],
      "Flying the back course with a conventional CDI gives reverse sensing, so correct away from the needle. An HSI set to the front course reads normally."),
    S(0, 2, "DME", "When is a DME groundspeed readout accurate?",
      ["Tracking straight to or from it", "Flying an arc around the station", "Crossing a radial at right angles"],
      "DME groundspeed comes from the rate of change of distance, so it is accurate only when tracking directly to or from the station."),
    S(0, 3, "Changeover point", "A COP is charted between two VORs. What should you do there?",
      ["Change to the VOR ahead", "Begin a climb to the next MEA", "Report the fix to ATC"],
      "A charted changeover point marks where to switch to the facility ahead because the one behind can't be relied on beyond it."),
    S(0, 2, "Course intercept", "Intercepting a VOR course inbound, a 30-degree intercept angle is used. Why turn before the needle centers?",
      ["To avoid overshooting", "To keep the TO flag showing", "To reduce DME slant error"],
      "Leading the turn as the needle starts to move keeps the airplane from overshooting, so it rolls out on the course rather than beyond it."),
]
